// Probe: verify ldmatrix fragment mappings for mma.m16n8k16 on sm_86.
// Dumps per-lane registers after ldmatrix.x4 (plain and .trans) from a
// row-major 32x32 bf16 shared matrix with value = row*64 + col.
#include <cuda_bf16.h>
#include <cstdio>
#include <cstdint>

__device__ __forceinline__ void ldmatrix_x4(uint32_t r[4], const void* smem_ptr, bool trans) {
    uint32_t addr = static_cast<uint32_t>(__cvta_generic_to_shared(smem_ptr));
    if (trans)
        asm volatile("ldmatrix.sync.aligned.m8n8.x4.trans.shared.b16 {%0,%1,%2,%3}, [%4];\n"
                     : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3]) : "r"(addr));
    else
        asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
                     : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3]) : "r"(addr));
}

// Address formula candidates for a 16x16 bf16 tile at (tile_row, tile_col)
// inside a row-major matrix with row_stride bytes.
// We only test formula: row = (l%8) + 8*((l/8)&1), col8 = 16*((l/8)>>1)
__global__ void probe_kernel(uint32_t* out_plain, uint32_t* out_trans, int row_stride_b) {
    __shared__ __align__(16) __nv_bfloat16 M[32][32];
    int tid = threadIdx.x;
    for (int i = tid; i < 32 * 32; i += blockDim.x)
        M[i / 32][i % 32] = __float2bfloat16((float)((i / 32) * 64 + (i % 32)));
    __syncthreads();

    int l = threadIdx.x % 32;
    // 16x16 tile: rows 8..23, cols 8..23 (offset so base isn't 0)
    const int TR = 8, TC = 8;
    const char* base = reinterpret_cast<const char*>(&M[TR][TC]);
    uint32_t addr_off = static_cast<uint32_t>(__cvta_generic_to_shared(base));
    // lane's address for matrix l/8, row l%8
    int row = (l % 8) + 8 * ((l / 8) & 1);
    int col_bytes = 16 * ((l / 8) >> 1);
    uint32_t addr = addr_off + (uint32_t)(row * row_stride_b + col_bytes);

    uint32_t rp[4], rt[4];
    asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
                 : "=r"(rp[0]), "=r"(rp[1]), "=r"(rp[2]), "=r"(rp[3]) : "r"(addr));
    asm volatile("ldmatrix.sync.aligned.m8n8.x4.trans.shared.b16 {%0,%1,%2,%3}, [%4];\n"
                 : "=r"(rt[0]), "=r"(rt[1]), "=r"(rt[2]), "=r"(rt[3]) : "r"(addr));
    for (int i = 0; i < 4; ++i) { out_plain[l * 4 + i] = rp[i]; out_trans[l * 4 + i] = rt[i]; }
}

